# note missing row9 zeros

g=[[0]*11 for _ in range(11)]
for r,cs in rows1.items():
 for c in cs:
  rr=r+1; cc=c+1
  if rr<11 and cc<11 and inp[rr][cc]!=2:g[rr][cc]=3
for r in range(11):
 for c in range(11):
  if inp[r][c]==2:g[r][c]=2
  if inp[r][c]==3:g[r][c]=3
